create table public.carts (id uuid primary key default gen_random_uuid(), customer_user_id uuid not null unique references public.profiles(user_id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.cart_items (id uuid primary key default gen_random_uuid(), cart_id uuid not null references public.carts(id) on delete cascade, item_type text not null, product_id uuid references public.products(id) on delete restrict, service_id uuid references public.services(id) on delete restrict, quantity integer not null default 1, created_at timestamptz not null default now(), constraint cart_item_type check (item_type in ('product','service')), constraint cart_item_reference check ((item_type='product' and product_id is not null and service_id is null) or (item_type='service' and service_id is not null and product_id is null)), constraint cart_item_quantity check (quantity > 0));
create unique index cart_product_unique on public.cart_items(cart_id, product_id) where item_type='product'; create unique index cart_service_unique on public.cart_items(cart_id, service_id) where item_type='service';
create trigger carts_set_updated_at before update on public.carts for each row execute function public.set_updated_at();
alter table public.carts enable row level security; alter table public.cart_items enable row level security;
create policy "carts own" on public.carts for all to authenticated using (customer_user_id=(select auth.uid())) with check (customer_user_id=(select auth.uid()));
create policy "cart items own" on public.cart_items for all to authenticated using (exists (select 1 from public.carts c where c.id=cart_id and c.customer_user_id=(select auth.uid()))) with check (exists (select 1 from public.carts c where c.id=cart_id and c.customer_user_id=(select auth.uid())));
grant select, insert, update, delete on public.carts, public.cart_items to authenticated;
